                "type": "string",
                "description": "Model override for the CLI agent, as a model id that CLI accepts. Valid ids are per-CLI and change between vendor releases — read them from that agent rather than from any list. Uses user-configured default if omitted."
              },
              "modelTier": {
                "type": "string",
                "enum": [
                  "opus",
                  "sonnet",
                  "haiku"
                ],
                "description": "Model capability tier for Ptah CLI agents. Controls which model tier the spawned agent uses. \"opus\" = most capable (complex architecture, deep analysis), \"sonnet\" = balanced (default, general coding tasks), \"haiku\" = fastest (simple tasks, quick lookups). The tier maps to a concrete model through the chosen provider's own tier mappings, so the same tier resolves differently per provider — you pick the tier, never the model id. Only applies when ptahCliId is set. Ignored for standard CLI agents."
              },
              "resume_session_id": {
                "type": "string",
                "description": "Resume a previous CLI agent session by its CLI-native session ID. The agent will continue from where the previous session left off."
              },
              "role": {
                "type": "string",
                "description": "Name of an agent role generated for this workspace. ptah_agent_list shows the valid names. The role definition is delivered to the agent, and the spawn result reports how it was delivered. Do not paste a role template into task; pass its name here instead."
              },
              "effort": {
                "type": "string",
                "description": "Reasoning effort for this lane: minimal, low, medium, high, xhigh or max. Wins over the per-CLI setting and the chat effort. A value the chosen CLI does not take is ignored. Omit to use the setting."
              }
            },
            "required": [
              "task"
            ]
          }
        },
        {
          "tool_name": "ptah__ptah_harness_install_mcp_server",
          "description": "Harness-builder tool: install an MCP server into the workspace by writing its transport config to the selected target config files (claude -> .mcp.json, vscode -> .vscode/mcp.json, cursor -> .cursor/mcp.json, copilot -> ~/.copilot/mcp-config.json). Defaults to [\"claude\",\"vscode\"]. Discover a server first with ptah_harness_search_mcp_registry and check ptah_harness_list_installed_mcp so you do not re-install one that is already configured. You must supply the transport config yourself — the registry entry tells you the package/URL. Returns the resolved server key, the config files written, and per-target warnings. NOTE: the server becomes available to a NEW agent session, not the current one.",
          "score": 4.033392429351807,
          "input_schema": {
            "type": "object",
            "properties": {
              "serverName": {
                "type": "string",
                "description": "Fully qualified registry name used for install tracking (e.g. \"io.github.owner/server\")."
              },
              "config": {
                "type": "object",
                "description": "Transport config. stdio: {\"type\":\"stdio\",\"command\":\"npx\",\"args\":[\"-y\",\"pkg\"],\"env\":{}}. Remote: {\"type\":\"http\"|\"sse\",\"url\":\"https://...\",\"headers\":{}}. \"env\" and \"headers\" are string-to-STRING maps — a numeric value such as {\"PORT\":3000} is rejected, send {\"PORT\":\"3000\"}. \"command\" and \"url\" must be non-empty."
              },
              "serverKey": {
                "type": "string",
                "description": "Optional config key (e.g. \"github\"). Defaults to the last path segment of serverName, sanitized."
              },
              "targets": {
                "type": "array",
                "minItems": 1,
                "items": {
                  "type": "string",
                  "enum": [
                    "vscode",
                    "claude",
                    "cursor",
                    "copilot",
                    "codex",
                    "antigravity",
                    "opencode"
                  ]
                },
                "description": "Optional install targets. Defaults to [\"claude\",\"vscode\"]. An EMPTY array is rejected — omit the key to take the default."
              }
            },
            "required": [
              "serverName",
              "config"
            ]
          }
        },
        {
          "tool_name": "ptah__ptah_agent_stop",
          "description": "Stop a running agent. Sends SIGTERM, waits 5 seconds, then SIGKILL. If agent is already completed, returns its final status without error.",
          "score": 3.896190643310547,
          "input_schema": {
            "type": "object",
            "properties": {
              "agentId": {
                "type": "string",
                "description": "Agent ID to stop"
