          "score": 3.690138816833496,
          "input_schema": {
            "type": "object",
            "properties": {
              "agentId": {
                "type": "string",
                "description": "Agent ID to message"
              },
              "message": {
                "type": "string",
                "description": "Message text to deliver to the agent (max 102400 characters)"
              }
            },
            "required": [
              "agentId",
              "message"
            ]
          }
